oxy_webhelp_navlinks = {"how_blocking_works_agent_cloud-d37755e62948":{"topics":[{"title":"Blocking support by connection","shortdesc":"<p class=\"shortdesc\">Which items <span class=\"ph\">Agent Cloud<\/span> can block, and whether Ask is supported, depends on         the connection. Check this table before you set a policy to Block.<\/p>","href":"agent_cloud\/how_blocking_works_agent_cloud.html#tool_blocking_support","attributes":{"data-id":"tool_blocking_support"},"menu":{"hasChildren":false},"tocID":"tool_blocking_support-d37755e62962","topics":[]},{"title":"What happens when an action is blocked","shortdesc":"<p class=\"shortdesc\">When a Block policy denies an item, <span class=\"ph\">Agent Cloud<\/span> withholds that item and the         rest of the agent's turn continues. The policy alert appears after <span class=\"ph\">Agent Cloud<\/span>         processes the session.<\/p>","href":"agent_cloud\/how_blocking_works_agent_cloud.html#blocked_action_behavior_agent_cloud","attributes":{"data-id":"blocked_action_behavior_agent_cloud"},"menu":{"hasChildren":false},"tocID":"blocked_action_behavior_agent_cloud-d37755e62976","topics":[]},{"title":"Blocking limitations and fail-open behavior","shortdesc":"<p class=\"shortdesc\">Real-time blocking stops what it can inline, and the monitoring that follows each         session catches the rest. Know these limits before you rely on a Block policy.<\/p>","href":"agent_cloud\/how_blocking_works_agent_cloud.html#blocking_limitations_agent_cloud","attributes":{"data-id":"blocking_limitations_agent_cloud"},"menu":{"hasChildren":false},"tocID":"blocking_limitations_agent_cloud-d37755e62993","topics":[]}]}};